css:
.textcenter{
        text-align:center;
}
.borderclass{
    border-bottom: 1px solid dodgerblue;
}
table {
    width:100%;
    text-align:left;
    border-collapse: collapse;
}

table, td, th {
    /*width:50%;*/
    border: 1px solid dodgerblue;
    font-size:10px;

}
.print-format{
    padding: 12px !important;
    margin-bottom: 0px;
    margin-top:0px;
}

html:
{%- for item in doc.items -%}
{%- if item.batch_no -%}

{% set batch = frappe.get_doc("Batch", item.batch_no) %}

{% if batch.quality_inspection %}
    {% set c = frappe.get_doc("Quality Inspection", batch.quality_inspection) %}
{% endif %}

{% if c and c.quality_inspection_template %}
    {% set b = frappe.get_doc("Quality Inspection Template", c.quality_inspection_template) %}
{% endif %}

{% if item.sales_order and doc.customer %}
    {% set sta = frappe.db.get_value("Customer Quality Inspection",
        {"sales_order": item.sales_order, "customer": doc.customer}, "name") %}
{% endif %}

{% if sta %}
    {% set st = frappe.get_doc("Customer Quality Inspection",
        {"sales_order": item.sales_order, "item": item.item_code, "customer": doc.customer}) %}
{% endif %}

<table>
<tr><td>{{ letter_head }}</td></tr>
</table>

<div style="text-align:center;font-size:16px;">
<b>CERTIFICATE OF ANALYSIS</b>
</div>
<br>

<table>
<tr>
<td style="width:50%">
<b>Product</b>: {{ item.item_name }}<br>
<b>Customer Name</b>: {{ doc.customer_name }}<br>
<b>Invoice No</b>: {{ doc.name }}<br>
<b>Dated</b>: {{ doc.get_formatted("posting_date") }}<br>
</td>

<td style="width:50%">
<b>Batch No</b>: {{ item.batch_no }}<br>
<b>Date of Mfg.</b>: {{ batch.get_formatted("manufacturing_date") if batch.manufacturing_date else "" }}<br>

{% if batch.expiry_date %}
<b>Date of Exp.</b>: {{ batch.get_formatted("expiry_date") }}<br>
{% endif %}

<b>Quantity</b>: {{ item.qty }}<br>
</td>
</tr>
</table>

<br>

<table border="1" style="width:100%; border-collapse:collapse;">
<tr>
<th>Sr No.</th>
<th>Test Parameters</th>
<th>Specification</th>
<th>Result</th>
<th>Remark</th>
</tr>

{% set ns = namespace(counter=0) %}

{% for i in batch.test_result %}

    {% if i.custom_coa_print_ | lower | trim == "yes" %}

        {% if sta %}

            {% for j in st.item_quality_inspection_parameter %}

                {% if j.specification == i.specification and j.custom_coa_print_ | lower | trim == "yes" %}

                    {% set ns.counter = ns.counter + 1 %}

                    <tr>
                        <td>{{ ns.counter }}</td>
                        <td>{{ j.specification }}</td>

                        <td>
                            {% if i.min_value == j.min_value %}
                                between {{ j.min_value }} and {{ j.max_value }}
                            {% elif j.acceptance_formula == i.acceptance_formula %}
                                {{ j.acceptance_formula }}
                            {% elif i.value == j.value %}
                                {{ j.value }}
                            {% else %}
                                {% if b %}
                                    {% for x in b.item_quality_inspection_parameter %}
                                        {% if x.specification == i.specification and x.values %}
                                            {{ x.values }}
                                        {% endif %}
                                    {% endfor %}
                                {% endif %}
                            {% endif %}
                        </td>

                        <td>
                            {% if i.reading_1 %}
                                {{ i.reading_1 }}
                            {% elif i.reading_value %}
                                {{ i.reading_value }}
                            {% else %}
                                {{ i.parameter_value }}
                            {% endif %}
                        </td>

                        <td>{{ i.status }}</td>
                    </tr>

                {% endif %}

            {% endfor %}

        {% else %}

            {% set ns.counter = ns.counter + 1 %}

            <tr>
                <td>{{ ns.counter }}</td>
                <td>{{ i.specification }}</td>

                <td>
                    {% if i.min_value %}
                        between {{ i.min_value }} and {{ i.max_value }}
                    {% elif i.acceptance_formula %}
                        {{ i.acceptance_formula }}
                    {% elif i.value %}
                        {{ i.value }}
                    {% else %}
                        {% if b %}
                            {% for x in b.item_quality_inspection_parameter %}
                                {% if x.specification == i.specification and x.values %}
                                    {{ x.values }}
                                {% endif %}
                            {% endfor %}
                        {% endif %}
                    {% endif %}
                </td>

                <td>
                    {% if i.reading_1 %}
                        {{ i.reading_1 }}
                    {% elif i.reading_value %}
                        {{ i.reading_value }}
                    {% else %}
                        {{ i.parameter_value }}
                    {% endif %}
                </td>

                <td>{{ i.status }}</td>
            </tr>

        {% endif %}

    {% endif %}

{% endfor %}

</table>

<br>

<table style="width:100%">
<tr>
<td style="width:80%">
<b>The product confirms to the specification and is of standard quality.</b>
</td>

<td style="width:20%; text-align:center;">
<br><br>
Tested by: QC<br>
Department
</td>
</tr>
</table>

<br>

<div style="font-size:12px;">
This is computer generated Certificate of Analysis, hence no signature is required.
</div>

<div class="page-break"></div>

{%- endif -%}
{%- endfor -%}
